1	/* cholesky_numeric.c — method1 (Cholesky x[0]) FI target kernel.
2	
3	 * Reproduces the method1 field signature: a sparse-Cholesky-like numeric
4	 * factorization where a floating-point accumulator (d0) lives ACROSS a
5	 * data-dependent indirect-addressing sub-loop (factorize_preordered's
6	 * @1dc fmadd d0 -> indirect sub-loop -> @250 fmsub d0 -> @2c0 fsqrt d0 ->
7	 * @2c8 str d0). An F5/RAT-residue fault that swaps d0's mapping mid-loop
8	 * returns the value of ANOTHER live variable -> multi-bit aliasing (method1
9	 * popcount 21-32, NOT a single-bit SEU).
10	 *
11	 * Two variants selectable by argv:
12	 *   numeric-only   (default): just the factorization (method1's 1.0% rate).
13	 *   compute-both  (argv[2]="both"): recompute the chain twice and cross-check
14	 *                  (method1's 0.27% rate — the 4x lower rate under redundancy).
15	 *   The numeric/compute ratio is method1's state-leak signature (target ∈[2,8]).
16	 *
17	 * Output: prints "x0_checksum=<16-hex> fails=N iters=N" where fails counts
18	 * mismatches between the factorization and a golden recompute. libc-only,
19	 * no vectorization (scalar FMA chain to keep d0 long-lived in a reg).
20	 *
21	 * Compile: gcc -static -O2 -o cholesky_numeric cholesky_numeric.c
22	 *   (avoid -ffast-math; we want IEEE754 determinism for golden recompute)
23	 */
24	#include <stdint.h>
25	#include <stdlib.h>
26	#include <stdio.h>
27	#include <math.h>
28	#include <string.h>
29	
30	/* matrix dimension. method1 field threshold N>=256; gem5 O3 uses
31	 * smaller N (64) for verifiability — the residue mechanism is N-independent. */
32	static int Nn = 64;
33	#define NZ (N*8) /* sparse: ~8 nonzeros/row */
34	#define MAXN 256  /* static array cap; Nn<=MAXN */
35	
36	/* xorshift32 RNG for deterministic test matrices. */
37	static uint32_t rng_s = 0x5A5A1234u;
38	static inline uint32_t xs32(void){uint32_t x=rng_s;x^=x<<13;x^=x>>17;x^=x>>5;rng_s=x;return x;}
39	
40	/* A simple symmetric positive-definite sparse matrix (CSC-ish, per-row
41	 * index+value arrays). Built so the Cholesky factor L has a long-lived
42	 * diagonal accumulator d0 that spans an indirect-addressing sub-loop. */
43	static int    col_idx[MAXN][8];
44	static double col_val[MAXN][8];
45	static double diag[MAXN];      /* diagonal of L (the d0 chain) */
46	static double Lrow[MAXN][MAXN];   /* dense lower triangle (small N, kept for golden) */
47	
48	static void build_matrix(void) {
49	    for (int i = 0; i < Nn; i++) {
50	        for (int k = 0; k < 8; k++) {
51	            int j = (i + k + 1) % Nn;
52	            if (j <= i) j = (j + i + 1) % Nn;
53	            col_idx[i][k] = j;
54	            col_val[i][k] = (double)(xs32() % 1000) / 1000.0 + 0.1;
55	        }
56	        /* make SPD-ish: strong diagonal */
57	        col_val[i][0] = (double)(i + 10);
58	    }
59	}
60	
61	/* numeric Cholesky factorization (left-looking). d0 = L[i][i] is the
62	 * long-lived accumulator: fmadd across the j<k sub-loop, fmsub to update,
63	 * fsqrt for the diagonal, str to store. A residue fault on d0 mid-loop
64	 * returns another variable's value -> multi-bit x[0] aliasing. */
65	static void factorize(double L[MAXN][MAXN]) {
66	    for (int k = 0; k < Nn; k++) {
67	        /* d0 lives across the j-loop (the indirect-addressing sub-loop).
68	         * Plain C (-O2 keeps the accumulator in a register across the loop,
69	         * modeling method1's cross-loop-live d0 without hard-binding a reg). */
70	        double d0 = 0.0;
71	        for (int j = 0; j < k; j++) {
72	            double s = 0.0;
73	            for (int t = 0; t < 8 && col_idx[j][t] < j; t++) {
74	                int c = col_idx[j][t];
75	                s += L[k][c] * L[j][c];
76	            }
77	            d0 -= s * L[j][k];   /* fmsub: d0 = d0 - s*L[j][k] */
78	        }
79	        double akk = col_val[k][0];
80	        d0 = akk - d0;
81	        d0 = sqrt(d0);
82	        diag[k] = d0;
83	        L[k][k] = d0;
84	        /* column update: L[i][k] = (A[i][k] - sum) / L[k][k] for i>k */
85	        for (int i = k+1; i < Nn; i++) {
86	            double s = 0.0;
87	            for (int j = 0; j < 8 && col_idx[i][j] < k; j++) {
88	                int c = col_idx[i][j];
89	                if (c < k) s += L[i][c] * L[k][c];
90	            }
91	            double aik = (i < Nn && k < 8) ? col_val[i][k % 8] : 0.0;
92	            L[i][k] = (aik - s) / d0;   /* d0 consumed here — residue reads */
93	        }
94	    }
95	}
96	
97	/* Solve L * x = b (forward substitution), return x[0] — method1's corrupted
98	 * element. x[0] = (b[0]) / L[0][0] (one hop through the d0 diagonal chain). */
99	static double solve_x0(double L[MAXN][MAXN], double b[MAXN]) {
100	    double x0 = b[0] / L[0][0];
101	    return x0;
102	}
103	
104	int main(int argc, char **argv) {
105	    long iters = (argc > 1) ? atol(argv[1]) : 10;
106	    if (argc > 3) Nn = atoi(argv[3]);
107	    if (Nn > 256) Nn = 256;  /* static arrays cap */
108	    int both = (argc > 2 && strcmp(argv[2], "both") == 0);
109	    build_matrix();
110	
111	    long fails = 0;
112	    uint64_t x0_acc = 0;   /* accumulate x[0] across iters for a checksum */
113	    for (long it = 0; it < iters; it++) {
114	        rng_s = (uint32_t)(0x9e3779b9u * (it + 1));
115	        build_matrix();
116	
117	        double b[MAXN];
118	        for (int i = 0; i < Nn; i++) b[i] = (double)(xs32() % 1000) / 100.0;
119	
120	        /* golden: factorize into a SEPARATE matrix Lg, no residue */
121	        static double Lg[MAXN][MAXN];
122	        memset(Lg, 0, sizeof(Lg));
123	        factorize(Lg);
124	        double x0_gold = solve_x0(Lg, b);
125	
126	        double x0_run;
127	        if (both) {
128	            /* compute-both: re-factorize and cross-check (method1's 0.27%
129	             * path — redundant recompute suppresses state-leak SDC 4x) */
130	            static double L2[MAXN][MAXN];
131	            memset(L2, 0, sizeof(L2));
132	            factorize(L2);
133	            double x0_2 = solve_x0(L2, b);
134	            x0_run = x0_2;
135	            if (x0_2 != x0_gold) fails++;   /* cross-check mismatch */
136	        } else {
137	            /* numeric-only: single factorization (method1's 1.0% path) */
138	            static double L1[MAXN][MAXN];
139	            memset(L1, 0, sizeof(L1));
140	            factorize(L1);
141	            x0_run = solve_x0(L1, b);
142	            if (x0_run != x0_gold) fails++;
143	        }
144	        /* fold x0 into a 16-hex-ish checksum (low bits) */
145	        uint64_t bits;
146	        memcpy(&bits, &x0_run, sizeof(bits));
147	        x0_acc ^= bits * (it + 1);
148	    }
149	    /* print a 16-hex checksum of x0_acc for classify.py, plus fail count */
150	    printf("%016lx\n", x0_acc & 0xFFFFFFFFFFFFFFFFULL);
151	    fprintf(stderr, "iters=%ld fails=%ld variant=%s\n",
152	            iters, fails, both ? "compute-both" : "numeric-only");
153	    return (fails > 0) ? 1 : 0;
154	}

