            << ", CPU: " << cpu->name()
            << ", Thread: " << tid
            << ", Site: l1d_post_check_escape"
            << ", Mask: 0x" << std::hex << mask << std::dec
            << (!semantic_role.empty() ? ", SemanticRole: " + semantic_role : "")
            << std::endl;
    }

