            case Mode::EntryBitFlip: return "entry_bitflip";
            case Mode::ExcSuppress: return "exc_suppress";
            case Mode::SpecLeak:     return "spec_leak";  // G7: clear -Wswitch
        }
        return "?";
    }

    void
    CHAOSROB::scheduleAttackEvent(Cycles delay)
