__attribute__((noinline)) static uint64_t l2(uint64_t v) { return leaf(v) ^ 0x5a5a; }
__attribute__((noinline)) static uint64_t l3(uint64_t v) { return l2(v) + leaf(v ^ 0xff); }

int main(int argc, char **argv) {
