        acc += l3((uint64_t)i);
        acc ^= l2(acc);
    }
    printf("%016lx\n", acc & 0xFFFFFFFFFFFFFFFFULL);
    fprintf(stderr, "iters=%ld fails=0 variant=call_ret_heavy\n", iters);
    return 0;
}
